/* Shared navigation, accessible vector icons, and the mobile scenario summary. */
(()=>{'use strict';
const $=id=>document.getElementById(id),paths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',route:'<circle cx="5" cy="5" r="2"/><circle cx="19" cy="19" r="2"/><path d="M7 5h9a4 4 0 0 1 0 8H8a3 3 0 0 0 0 6h9"/>',matchup:'<path d="M4 7h13l-3-3m3 3-3 3M20 17H7l3 3m-3-3 3-3"/>',trophy:'<path d="M8 3h8v6a4 4 0 0 1-8 0ZM8 5H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4m-4 1v6m-4 2h8m-4-2H9"/>',pulse:'<path d="M3 12h4l3-8 4 16 3-8h4"/>',medal:'<circle cx="12" cy="10" r="6"/><path d="m8 15-2 7 6-3 6 3-2-7m-6-12 2 3 2-3"/>',receipt:'<path d="M5 3h14v19l-3-2-4 2-4-2-3 2ZM9 8h6m-6 4h6m-6 4h3"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="1.5"/><path d="m21 16-6-6L5 21"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',external:'<path d="M14 3h7v7m0-7L10 14M9 3H4a1 1 0 0 0-1 1v16a1 1 0 0 0 1 1h16a1 1 0 0 0 1-1v-5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',bookmark:'<path d="M5 3h14v19l-7-4-7 4Z"/>',share:'<path d="M12 16V3m-5 5 5-5 5 5M5 12H3v8a1 1 0 0 0 1 1h16a1 1 0 0 0 1-1v-8h-2"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',undo:'<path d="M3 9h11a7 7 0 0 1 0 14m-7-20-4 6 4 5" transform="translate(0 -1)"/>',redo:'<path d="M21 8H10a7 7 0 0 0 0 14m7-20 4 6-4 5"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M6 6a8 8 0 0 1 13 3M5 15a8 8 0 0 0 13 3"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 15v6h16v-6"/>','chevron-left':'<path d="m15 5-7 7 7 7"/>','chevron-right':'<path d="m9 5 7 7-7 7"/>',check:'<path d="m5 12 4 4L20 5"/>'};
function icon(name){return '<svg class="ui-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false">'+(paths[name]||paths.arrow)+'</svg>'}
const symbols={'↗':'external','↻':'refresh','↓':'download','×':'close','↶':'undo','↷':'redo','⌕':'search'};
function hydrate(root=document){root.querySelectorAll('[data-icon]').forEach(e=>{if(!e.querySelector('svg'))e.innerHTML=icon(e.dataset.icon)});root.querySelectorAll('button,a,.search>span').forEach(el=>{let walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode())if(/[↗↻↓×↶↷⌕]/.test(walker.currentNode.textContent))nodes.push(walker.currentNode);nodes.forEach(n=>{let f=document.createDocumentFragment();for(let segment of n.textContent.split(/([↗↻↓×↶↷⌕])/)){if(symbols[segment]){let tmp=document.createElement('span');tmp.innerHTML=icon(symbols[segment]);tmp.setAttribute('aria-hidden','true');f.append(tmp)}else f.append(document.createTextNode(segment))}n.replaceWith(f)})})}
const labels={hq:'Browns HQ',simulator:'Playoff simulator',road:'Road to January',matchup:'Matchup lab',pickem:'Fan pick’em',confidence:'Confidence meter',awards:'Season awards',receipts:'Receipt tracker',graphics:'Graphic factory'},aliases={hq:'home scores scoreboard live',simulator:'odds predictions playoffs winners pick games',road:'record path scenarios wins',matchup:'opponent statistics stats offense defense',pickem:'picks league friends contest',confidence:'poll polls votes opinions',awards:'mvp ballot votes players',receipts:'prediction takes timestamp',graphics:'images download cards score'};
let current=document.body.dataset.currentView||'hq',gamesScroll=0;
function openFeatures(){let d=$('featureDialog');if(d.open)return;$('featureSearch').value='';filterFeatures();d.showModal();$('featureSearch').focus()}
function closeFeatures(){$('featureDialog').close()}
function filterFeatures(){let q=$('featureSearch').value.trim().toLowerCase(),tokens=q.split(/\s+/).filter(Boolean),found=0;document.querySelectorAll('.feature-choice').forEach(b=>{let text=(b.textContent+' '+aliases[b.dataset.hub]).toLowerCase(),show=tokens.every(t=>text.includes(t));b.hidden=!show;if(show)found++});$('featureNoResults').hidden=found>0}
function syncDock(){let show=current==='simulator'&&!!output&&!document.body.classList.contains('odds-view');$('scenarioDock').hidden=!show;if(!output)return;$('dockTeam').textContent=short(focus).toUpperCase()+' PLAYOFF ODDS';$('dockOdds').textContent=percent(output.result[focus].play);$('dockPicks').textContent=document.body.classList.contains('is-computing')?'Updating…':Object.keys(picks).length+' picks';document.querySelector('[data-scenario-undo]').disabled=!undoStack.length}
function updateChrome(key){current=key;document.body.dataset.currentView=key;document.body.classList.toggle('simulator-mode',key==='simulator');$('pageContext').textContent=labels[key]||'Browns HQ';document.title=(labels[key]||'Browns HQ')+' · TEMU PLAYOFF PREDICTOR';document.querySelectorAll('[data-hub]').forEach(b=>{let selected=b.dataset.hub===key;b.classList.toggle('active',selected);if(selected)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});$('moreFeatures').classList.toggle('active',!['hq','simulator','matchup'].includes(key));if($('featureDialog').open)closeFeatures();hydrate();syncDock()}
document.querySelectorAll('[data-open-features]').forEach(b=>b.onclick=openFeatures);document.querySelector('[data-close-features]').onclick=closeFeatures;document.querySelectorAll('[data-utility]').forEach(b=>b.onclick=()=>{closeFeatures();$(b.dataset.utility).click()});$('featureSearch').oninput=filterFeatures;$('featureDialog').addEventListener('click',e=>{if(e.target===$('featureDialog')){let r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeFeatures()}});$('featureSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){let first=[...document.querySelectorAll('.feature-choice')].find(b=>!b.hidden);if(first){e.preventDefault();first.click()}}});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if($('featureDialog').open)closeFeatures();else openFeatures()}});
$('dockViewOdds').onclick=()=>{gamesScroll=window.scrollY;document.querySelector('[data-view="odds"]').click();requestAnimationFrame(()=>{$('oddsPanel').scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})})};document.querySelector('[data-scenario-undo]').onclick=()=>$('undo').click();document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-view]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));syncDock();if(b.dataset.view==='games'&&gamesScroll)requestAnimationFrame(()=>window.scrollTo({top:gamesScroll,behavior:'auto'}))}));
document.addEventListener('lab:route',e=>updateChrome(e.detail.view));document.addEventListener('lab:update',()=>{hydrate();syncDock();document.body.classList.remove('initial-loading')});document.addEventListener('lab:state',syncDock);document.addEventListener('lab:hubrender',()=>hydrate($('hubView')));window.addEventListener('pageshow',syncDock);
updateChrome(current);document.body.classList.toggle('initial-loading',!output);hydrate();
})();
